package com.chilicraft.quest;
import com.chilicraft.api.*; import org.bukkit.command.*; import org.bukkit.entity.Player; import java.util.*;
final class QuestCommand implements ModuleCommandExecutor,ModuleTabCompleter { private final ChiliQuestPlugin plugin; private final QuestService service; private final QuestGui gui; private final QuestSettings settings; QuestCommand(ChiliQuestPlugin p,QuestService s,QuestGui g,QuestSettings q){plugin=p;service=s;gui=g;settings=q;} public boolean execute(CommandSender sender,String[] a){if(a.length==0||a[0].equalsIgnoreCase("guide")){if(sender instanceof Player p)gui.open(p);else sender.sendMessage(settings.message("players-only","只能由玩家执行。"));return true;}if(a[0].equalsIgnoreCase("status")){if(sender instanceof Player p){var cs=service.chapters();sender.sendMessage(settings.message("status","当前章节：<chapter>；任务：<quest>").replace("<chapter>",cs.isEmpty()?"-":cs.get(0).title()));}return true;}if(a[0].equalsIgnoreCase("claim")&&a.length>1&&sender instanceof Player p){sender.sendMessage(settings.message("claiming","正在领取，请稍候。"));service.claim(p,a[1],result->{switch(result.status()){case SUCCESS->p.sendMessage(settings.message("claimed","已领取。"));case ALREADY_CLAIMED->p.sendMessage(settings.message("already-claimed","已领取。"));case QUEST_NOT_COMPLETED,PLAYER_NOT_FOUND->p.sendMessage(settings.message("not-completed","尚未完成或不存在。"));case CONFLICT->p.sendMessage(settings.message("claim-conflict","状态发生变化，请重试。"));default->p.sendMessage(settings.message("claim-failed","领取失败，请稍后重试。"));}});return true;}if(a[0].equalsIgnoreCase("admin")&&sender.hasPermission("chilicraft.quest.admin")){if(a.length>1&&a[1].equalsIgnoreCase("reload")){plugin.reloadQuest();sender.sendMessage(settings.message("loaded","已加载。"));return true;}if(a.length>2&&a[1].equalsIgnoreCase("reset")){try{UUID id=UUID.fromString(a[2]);service.reset(id,()->sender.sendMessage(settings.message("reset","已重置。")));}catch(IllegalArgumentException ignored){}return true;}}sender.sendMessage(settings.message("usage","用法错误。"));return true;}public List<String> complete(CommandSender s,String[] a){if(a.length==1)return List.of("guide","status","claim","admin").stream().filter(x->x.startsWith(a[0].toLowerCase(Locale.ROOT))&&(!x.equals("admin")||s.hasPermission("chilicraft.quest.admin"))).toList();if(a.length==2&&a[0].equalsIgnoreCase("admin"))return List.of("reload","reset");return List.of();}}
